# Fresh Count20 r11 source-bound metadata guard. No native, lock, compiler, GUI, or remote action.
[CmdletBinding()]
param(
 [Parameter(Mandatory=$true)][string]$IssuedMetadataPath,[Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{64}$')][string]$IssuedMetadataHash,
 [Parameter(Mandatory=$true)][string]$FreshCasePath,[Parameter(Mandatory=$true)][string]$FreshTuplePath,[Parameter(Mandatory=$true)][string]$FreshManifestPath,[Parameter(Mandatory=$true)][string]$EquivalencePath,
 [Parameter(Mandatory=$true)][string]$ActualPlanPath,[Parameter(Mandatory=$true)][string]$ActualReceiptPath,[Parameter(Mandatory=$true)][string]$ExecutablePath,
 [Parameter(Mandatory=$true)][string]$ControlOutputPath,[Parameter(Mandatory=$true)][string]$RunRoot,[Parameter(Mandatory=$true)][ValidateSet(20)][int]$Count=20,
 [Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{64}$')][string]$CompileReceiptSha256,[Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{64}$')][string]$ExeSha256,
 [Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{64}$')][string]$PlanSha256,[switch]$SkipFaultControls
)
$ErrorActionPreference='Stop';$expectedCaseHash='sha256:037c8e81cdc19fa488812bea6ed618aaa4ff8960a9b485fc60fc8c61dcc338de'
$expectedCaseRawHash='f9a8e685f55c8063fde159bfb58926c637cd740fc8c6edb71de702933b7e3878';$expectedCaseID='swiftui.padding-frame.recipe.gate-seeded.ca4e13f820f5d258.r11.h13bfe5b8fbd9';$expectedTupleID='sr1-source-bound-r11-mac20-host-13bfe5b8fbd9-20261011';$expectedV4='aa8f39419292d2170b9036f6ee648bf8b71f9ca9ddcf6205d1a03ea0b2f2f34d'
function Full([string]$p){[IO.Path]::GetFullPath($p)};function Hash([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()};function Ref([string]$p){$i=Get-Item -LiteralPath $p;[ordered]@{path=(Full $p);sha256=('sha256:'+(Hash $p));bytes=[int64]$i.Length}}
function Require([string]$p){if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw "Required file missing: $p"}}
foreach($p in @($IssuedMetadataPath,$FreshCasePath,$FreshTuplePath,$FreshManifestPath,$EquivalencePath,$ActualPlanPath,$ActualReceiptPath,$ExecutablePath)){Require $p}
if((Hash $IssuedMetadataPath) -cne $IssuedMetadataHash){throw 'Issued metadata hash mismatch'};if((Hash $FreshCasePath) -cne $expectedCaseRawHash){throw 'Fresh case raw hash mismatch'};if((Hash $FreshTuplePath) -cne 'bf5978000391687733885d3e49465e79e7727f374488cb359595a085113422c0'){throw 'Fresh tuple packet hash mismatch'};if((Hash $FreshManifestPath) -cne 'e39db8b6d3844c6de9811eb5783564b49eb8556bc3cc854e79c3a36c61f8e9e0'){throw 'Fresh manifest hash mismatch'};if((Hash $EquivalencePath) -cne $expectedV4){throw 'v4 receipt hash mismatch'};if((Hash $ActualPlanPath) -cne $PlanSha256 -or (Hash $ActualReceiptPath) -cne $CompileReceiptSha256 -or (Hash $ExecutablePath) -cne $ExeSha256){throw 'Actual closure hash mismatch'}
$m=Get-Content -Raw $IssuedMetadataPath|ConvertFrom-Json;$case=Get-Content -Raw $FreshCasePath|ConvertFrom-Json;$packet=Get-Content -Raw $FreshTuplePath|ConvertFrom-Json;$manifest=Get-Content -Raw $FreshManifestPath|ConvertFrom-Json;$eq=Get-Content -Raw $EquivalencePath|ConvertFrom-Json;$plan=Get-Content -Raw $ActualPlanPath|ConvertFrom-Json;$receipt=Get-Content -Raw $ActualReceiptPath|ConvertFrom-Json
if($m.kind -cne 'factory-prelaunch-capture-metadata-v2' -or $m.expectedCount -ne 20 -or $m.runRoot -cne (Full $RunRoot) -or $m.frozenTupleBound -ne $false -or $m.historicalTemplateTupleClosed -ne $false -or $m.case.id -cne $expectedCaseID -or $m.case.hash -cne $expectedCaseHash -or $m.compile.sha256 -cne ('sha256:'+$CompileReceiptSha256) -or $m.exe.sha256 -cne ('sha256:'+$ExeSha256) -or $m.sourceHash -ne $manifest.sourceHash -or $m.qualification -cne 'sourceBoundCandidate-observation-only'){throw 'Fresh metadata context mismatch'}
if($case.id -cne $expectedCaseID -or $packet.candidateID -cne $expectedTupleID -or $packet.case.id -cne $expectedCaseID -or $packet.case.hash -cne $expectedCaseHash -or $m.recipe.sha256 -ne ('sha256:'+(Hash $FreshManifestPath)) -or $m.plan.sha256 -ne ('sha256:'+(Hash $ActualPlanPath))){throw 'Fresh metadata source joins mismatch'}
if($eq.status -cne 'reuse-admitted-source-equivalent-v4' -or $eq.candidateOnly -ne $true -or $eq.equivalence.semanticInputsEqual -ne $true -or $eq.requirements.freshMetadata -ne $true -or $eq.requirements.freshCaptureIDs -ne $true -or $eq.requirements.historicalDonorRelabel -ne $false){throw 'Fresh v4 receipt gate mismatch'}
$parent=Split-Path -Parent $IssuedMetadataPath;$tuplePath=Join-Path $parent 'candidate-tuple.json';$bindingPath=Join-Path $parent 'candidate-binding.json';$contextPath=Join-Path $parent 'candidate-context.json';foreach($p in @($tuplePath,$bindingPath,$contextPath)){Require $p}
if($m.candidateTuple.path -ne (Full $tuplePath) -or $m.sourceBoundCandidateTuple.path -ne (Full $bindingPath) -or $m.candidateContext.path -ne (Full $contextPath)){throw 'Fresh metadata candidate paths mismatch'}
$tuple=Get-Content -Raw $tuplePath|ConvertFrom-Json;$binding=Get-Content -Raw $bindingPath|ConvertFrom-Json;$context=Get-Content -Raw $contextPath|ConvertFrom-Json
if($tuple.kind -cne 'factory-source-bound-candidate-canonical-tuple-v1' -or $tuple.version -ne 1 -or $tuple.candidateID -ne $expectedTupleID -or $tuple.case.id -ne $expectedCaseID -or $tuple.case.hash -ne $expectedCaseHash -or $tuple.frozenTupleBound -ne $false -or $tuple.tuple.hostHashes.windows -ne ('sha256:'+$ExeSha256) -or $tuple.tuple.id -ne $expectedTupleID){throw 'Fresh tuple wrapper mismatch'}
if($binding.kind -cne 'factory-source-bound-candidate-binding-v1' -or $binding.version -ne 1 -or $binding.frozenTupleBound -ne $false -or $binding.canonicalTupleRef.path -ne (Full $tuplePath) -or $binding.canonicalTupleRef.sha256 -ne ('sha256:'+(Hash $tuplePath)) -or $binding.runtime.sourceCommit -ne $plan.runtimeSourceCommit -or $binding.renderer.sha256 -ne ('sha256:'+$plan.rendererSha256)){throw 'Fresh binding mismatch'}
if($context.candidateID -ne $expectedTupleID -or $context.case.hash -ne $expectedCaseHash -or $context.frozenTupleBound -ne $false){throw 'Fresh context mismatch'}
if(($receipt.runtimeModules|ConvertTo-Json -Depth 20 -Compress) -cne ($m.producedRuntimeModules|ConvertTo-Json -Depth 20 -Compress)){throw 'Runtime module closure mismatch'}
$rows=@($m.captures);if($rows.Count -ne 20 -or @($rows.captureID|Select-Object -Unique).Count -ne 20 -or @($rows.imageID|Select-Object -Unique).Count -ne 20){throw 'Fresh capture cardinality mismatch'};foreach($row in $rows){if($row.captureID -notmatch '^capture/[0-9a-f]{32}$' -or $row.imageID -notmatch '^image/[0-9a-f]{32}$' -or $null -ne $row.measuredHostIdentity -or $null -ne $row.measuredClockIdentity -or $row.measurementStatus -cne 'pending-actual-launch-joins'){throw 'Fresh capture identity mismatch'}}
if(Test-Path $ControlOutputPath){throw 'Control output exists'};[IO.Directory]::CreateDirectory((Split-Path -Parent $ControlOutputPath))|Out-Null
$faultControls=@()
if(-not $SkipFaultControls){
 foreach($fault in @('metadata-expected-count','metadata-case-id','metadata-run-root','metadata-frozen-tuple')){
  $scratch=Join-Path ([IO.Path]::GetTempPath()) ('factory-fresh-guard-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($scratch)|Out-Null
  $mutated=Join-Path $scratch 'issued-metadata.json';$q=Get-Content -Raw $IssuedMetadataPath|ConvertFrom-Json
  if($fault -ceq 'metadata-expected-count'){$q.expectedCount=19}elseif($fault -ceq 'metadata-case-id'){$q.case.id='wrong-case'}elseif($fault -ceq 'metadata-run-root'){$q.runRoot=([IO.Path]::GetFullPath($RunRoot)+'-wrong')}else{$q.frozenTupleBound=$true}
  $q|ConvertTo-Json -Depth 40|Set-Content -LiteralPath $mutated -Encoding UTF8
  $mutHash=Hash $mutated;$out=Join-Path $scratch 'fault.json';$args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$PSCommandPath,'-IssuedMetadataPath',$mutated,'-IssuedMetadataHash',$mutHash,'-FreshCasePath',$FreshCasePath,'-FreshTuplePath',$FreshTuplePath,'-FreshManifestPath',$FreshManifestPath,'-EquivalencePath',$EquivalencePath,'-ActualPlanPath',$ActualPlanPath,'-ActualReceiptPath',$ActualReceiptPath,'-ExecutablePath',$ExecutablePath,'-ControlOutputPath',$out,'-RunRoot',$RunRoot,'-Count','20','-CompileReceiptSha256',$CompileReceiptSha256,'-ExeSha256',$ExeSha256,'-PlanSha256',$PlanSha256,'-SkipFaultControls');& powershell.exe @args *> (Join-Path $scratch 'fault.log');$rc=$LASTEXITCODE
  if($rc -eq 0){throw ('Fresh guard fault accepted: '+$fault)}
  $faultControls+= [ordered]@{name=$fault;accepted=$false;rejected=$true;nativeWindowActions=0;compilerActions=0;lockActions=0;reason='actual guard rejected mutated metadata'}
 }
}
[ordered]@{kind='factory-fresh-count20-r11-guard-controls-v1';status='passed-source-only';issuedMetadataPath=(Full $IssuedMetadataPath);issuedMetadataSha256=$IssuedMetadataHash;count=20;v4Equivalence=(Ref $EquivalencePath);baseline=[ordered]@{accepted=$true;rejected=$false;nativeWindowActions=0};faultControls=$faultControls;nativeWindowActions=0;compilerActions=0;guiActions=0;remoteActions=0;lockActions=0;qualification='hold'}|ConvertTo-Json -Depth 20|Set-Content -LiteralPath $ControlOutputPath -Encoding UTF8
Get-Content -Raw $ControlOutputPath
